import java.io.BufferedInputStream;
import java.math.BigInteger;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();

        StringBuilder digits = new StringBuilder(n);
        for (int i = 0; i < n; i++) {
            digits.append((char) ('0' + fs.nextInt()));
        }

        String s = digits.toString();
        String answer = null;

        for (int len = 1; len <= n; len++) {
            if (s.charAt(0) == '0') break;

            String candidate = s.substring(0, len);
            BigInteger value = new BigInteger(candidate);
            int pos = 0;

            while (pos < n) {
                String current = value.toString();
                if (pos + current.length() > n ||
                    !s.regionMatches(pos, current, 0, current.length())) {
                    break;
                }
                pos += current.length();
                value = value.add(BigInteger.ONE);
            }

            if (pos == n) {
                answer = candidate;
                break;
            }
        }

        System.out.println(answer == null ? "" : answer);
    }

    private static class FastScanner {
        private final BufferedInputStream in = new BufferedInputStream(System.in);
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws Exception {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws Exception {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }
    }
}
